(3147, 'en', 'page-builder-shortcode-strings-32303', 'ff4f47aff5f5f396c11506e685a293b8', 'If you consent, your data is subject to automated processing to promote our actions by e-mail. They are kept for a maximum of five years from the last contact from you or your unsubscription. In accordance with the amended Data Protection Act of 6 January 1978, you have the right to access, rectify, delete and portable your data that you can exercise by contacting gisele.online@gisele-delorme.com.', 18, 22, '', 'VISUAL', 'vc_row-7/vc_column-0/vc_column_text-0: content', 2, '', 'f4c9cba42c8a03bf4bb9c31016151c2d', 'optional', 60, 0, NULL, 0),
(3148, 'en', 'page-builder-shortcode-strings-32303', '0ad5c2cfe207e9580b1f2f5369a30466', 'CUSTOMER ACCOUNT', 18, 23, '', 'LINE', 'vc_row-8/vc_column-0/vc_custom_heading-0: text', 2, '', '8bfb70d9d2fe38ca06c2b14f4d889eba', 'optional', 3, 0, NULL, 0),
(3149, 'en', 'page-builder-shortcode-strings-32303', '842051753e0b08a328507e2c9261574b', 'We collect this information in order to process your orders. They are kept for one year and are not reused for other purposes, nor communicated to third parties. To exercise your right of access, modification, deletion and portability of data concerning you, you can write to gisele.online@gisele-delorme.com.', 18, 24, '', 'VISUAL', 'vc_row-8/vc_column-0/vc_column_text-0: content', 2, '', '27d755cfc9931b804243e9d7a060ff57', 'optional', 46, 0, NULL, 0),
(3150, 'en', 'page-builder-shortcode-strings-32303', 'f2457b92c12beeb796bd96103e1ba632', 'YOUR RIGHTS', 18, 25, '', 'LINE', 'vc_row-9/vc_column-0/vc_custom_heading-0: text', 2, '', 'c45506ea8f10d94c78cafbffeaf7abff', 'optional', 2, 0, NULL, 0),
(3151, 'en', 'page-builder-shortcode-strings-32303', '721529c349b559f9de92c6da1656629c', 'You have the right to request: access to your personal data, rectification of your personal data, or the erasure or limitation of your personal data in certain circumstances provided for by applicable law. These rights are not absolute. Your consent to the processing of your personal data when you visit the Site, may be revoked by you at any time.\r\n\r\nIf you wish to request a copy of your personal data or exercise any of your rights, please contact us at gisele.online@gisele-delorme.com\r\n', 18, 26, '', 'VISUAL', 'vc_row-9/vc_column-0/vc_column_text-0: content', 2, '', 'df87aa48bf5cf2604af3ad28e9874cac', 'optional', 75, 0, NULL, 0),
(3165, 'en', 'page-builder-shortcode-strings-778', '96ecb5367e1b1c1e6ea7e7f17861ddbf', 'DO I NEED TO CREATE AN ACCOUNT TO PLACE AN ORDER?', 21, 3, '', 'LINE', 'vc_row-0/vc_column-0/vc_tta_tabs-0/vc_tta_section-0/vc_toggle-0: title', 0, '', '64961b01299902ffd67eca25d9fbe6f0', 'optional', NULL, 0, NULL, 0),
(3158, 'en', 'page-builder-shortcode-strings-32316', 'f28191c7691d54168a975f28ece48c99', '\r\n\r\nI am text block. Click edit button to change this text. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Ut elit tellus, luctus nec ullamcorper mattis, pulvinar dapibus leo.\r\n\r\n', 20, 1, '', 'VISUAL', 'vc_row-0/vc_column-0/vc_column_text-0: content', 0, '', '28a3ac8aabcc64accf79265eace76381', 'optional', NULL, 0, NULL, 0),
(3164, 'en', 'page-builder-shortcode-strings-778', '9c18174619b384febc0aa7f5289469d6', 'It is necessary to create an account to be able to place an order on the site Gisèle Delorme. This account will allow you to follow the evolution of your order.', 21, 2, '', 'VISUAL', 'vc_row-0/vc_column-0/vc_tta_tabs-0/vc_tta_section-0/vc_toggle-0: content', 0, '', '7105375b35dde130752a4d5b9d347e0c', 'optional', NULL, 0, NULL, 0),
