(3269, 'en', 'page-builder-shortcode-strings-32415', 'e378bb52e265532a1be029de9d35fe1d', '\r\n<p style=\"text-align: center;\">1 to 2 samples gifted with each order.</p>\r\n', 24, 4, '', 'VISUAL', 'vc_row-0/vc_column-1/vc_column_text-0: content', 2, '', '13de43dc83cf27a6e23cb1c6bbaba0e2', 'optional', 6, 0, NULL, 0),
(3268, 'en', 'page-builder-shortcode-strings-32415', '0d4e84c33ba708a64adeadb5c3b3436c', '\r\n<p style=\"text-align: center;\">Free shipping on any order 200€+ toward any EU countries and 250€+ internationally.</p>\r\n', 24, 2, '', 'VISUAL', 'vc_row-0/vc_column-0/vc_column_text-0: content', 2, '', '2679309530b37b88ab3c7ee0067bbfdb', 'optional', 14, 0, NULL, 0),
(3258, 'en', 'page-builder-shortcode-strings-32415', 'e6f723d7eebdf73fb28708d5f379c98e', 'FREE SHIPPING', 24, 1, '', 'LINE', 'vc_row-0/vc_column-0/vc_custom_heading-0: text', 2, '', 'ed1f9c4179d00b934841a4e7afb5f1d5', 'optional', 2, 0, NULL, 0),
(3279, 'en', 'page-builder-shortcode-strings-806', 'aef8b07616b2cac51d3c0cf34091da5c', '</p>\r\n<p style=\"text-align: center;\">In order to bring you a prompt response, please fill-in the following contact sheet below.</p>\r\n<p>', 25, 4, '', 'VISUAL', 'wpml_string_wrapper-0/vc_row-0/vc_column-0/vc_column_text-0: content', 0, '', '116c19a3a4bba14074754489a38d5c59', 'optional', NULL, 0, NULL, 0),
(3260, 'en', 'page-builder-shortcode-strings-32415', '688336d42609d7e78c5e6f0113309c26', 'SAMPLES', 24, 3, '', 'LINE', 'vc_row-0/vc_column-1/vc_custom_heading-0: text', 2, '', '70ca5fbede3a05e1ccc45c5d54ae86b1', 'optional', 1, 0, NULL, 0),
(3262, 'en', 'page-builder-shortcode-strings-32415', '36ca5dc55ffad3b145b0cc4e8c7ab346', 'PERSONALIZED ADVICE', 24, 5, '', 'LINE', 'vc_row-0/vc_column-2/vc_custom_heading-0: text', 2, '', '388225afa92da340f7b4be3df351b5bd', 'optional', 4, 0, NULL, 0),
(3280, 'en', 'page-builder-shortcode-strings-806', '88bb1a5f5aa6ee36490c217ba0fca31e', '</p>\r\n<p style=\"font-size: 12px;\">Gisèle Delorme Instituts collects your data in order to process your contact request. The required data are necessary for the follow-up of your request. In accordance with the Data Protection Act, you have the right to access, rectify and delete your data. You can also object, for legitimate reasons, to the use of your data. You alone can exercise these rights over your own data by contacting: Gisele Delorme Instituts, IT and freedoms correspondent, 88 bis, rue Michel Ange 75016 Paris France or at contact@gisele-delorme.com, specifying in the subject of the \"Personal rights\" letter and attaching a copy of your proof of identity.</p>\r\n<p>', 25, 5, '', 'VISUAL', 'wpml_string_wrapper-0/vc_row-0/vc_column-0/vc_column_text-1: content', 0, '', '9e59ae3ec3935a386637936c56bc1a9a', 'optional', NULL, 0, NULL, 0),
(3264, 'en', 'page-builder-shortcode-strings-32415', '6e3e2f374436b9f05d19af390ac01432', 'SECURE PAYMENT', 24, 7, '', 'LINE', 'vc_row-0/vc_column-3/vc_custom_heading-0: text', 2, '', '610f58461a04d85d0f3533f265e99c68', 'optional', 3, 0, NULL, 0),
(3270, 'en', 'page-builder-shortcode-strings-32415', '3ff6b0db0f488efa15d06f14a567bbe2', '\r\n<p style=\"text-align: center;\">Our beauty experts help you and answer any of your questions.</p>\r\n', 24, 6, '', 'VISUAL', 'vc_row-0/vc_column-2/vc_column_text-0: content', 2, '', '20b190a5447381a6ac269022730ea6bb', 'optional', 10, 0, NULL, 0),
(3271, 'en', 'page-builder-shortcode-strings-32415', '989200590a2969e903651f6a7ceaaf62', '\r\n<p style=\"text-align: center;\">Purchase securely with 3D Secure ™ (3DS) security.</p>\r\n', 24, 8, '', 'VISUAL', 'vc_row-0/vc_column-3/vc_column_text-0: content', 2, '', '1ae1ae584517348deda1db4c97917f71', 'optional', 9, 0, NULL, 0),
