(983, 3021, 'ka-ge', 10, 'Gisèle Delorme-ის პროდუქციის ხაზი შექმნილია ინდივიდუალურად შექმნილი მკურნალობის უზრუნველსაყოფად. თქვენს განკარგულებაშია „ინსტრუმენტების ყუთი“, რომლითაც შეგიძლიათ შექმნათ პერსონალიზებული მიდგომა მკურნალობის ყველა ეტაპზე. ', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(984, 3022, 'ka-ge', 10, 'მაგალითად, სილამაზის ცენტრში პროფესიონალის მიერ დასმული დიაგნოზიდან გამომდინარე, შეგიძლიათ ისარგებლოთ ერთი და იგივე პროდუქტის განსხვავებული თვისებებით. ეს შესაძლებელია სხვადასხვაგვარად გამოყენებული პროდუქტების და შრატების აქტიური ინგრედიენტების კომბინაციით, რომლებიც ინტეგრირებულია მკურნალობის თითქმის ყველა ეტაპზე.', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(985, 3023, 'ka-ge', 10, 'უფრო გასაგები რომ გახდეს, მოვიყვანოთ მაგალითი. მაგალითად, დიაგნოზიდან გამომდინარე, გამწმენდ ფაზაში ამქერცლავი კრემის გამოყენება შესაძლებელია 3 განსხვავებული გზით:', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(986, 3024, 'ka-ge', 10, '1. ნორმალური და ცხიმიანი კანისთვის შეგიძლიათ ისარგებლოთ ხელით პილინგით გამწმენდი მეთოდით, სანამ კანი სრულად არ გაიწმინდება.', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(987, 3025, 'ka-ge', 10, '2. მეორეს მხრივ, პიგმენტური ლაქების მქონე მკრთალი, მოწიფული კანისთვის, იგივე ამქერცლავი კრემი უნდა გამოიყენოთ Essential Glow-ს აღმდგენი შრატის კომბინაციაში, რათა ისარგებლოთ ორმაგი აქერცვლით. მექანიკური- კრემისა და ქიმიური- შრატში არსებული AHA-ს წყალობით. ', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(988, 3026, 'ka-ge', 10, '3. მგრძნობიარე და გაუწყლოებული კანისთვის, სკრაბი უნდა გამოიყენოთ გამწმენდ საშუალებად. წყლისა და სკრაბის კომბინაცია უზრუნველყოფს უფრო ნაზ მექანიკურ ზემოქმედებას. ', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(989, 3034, 'ka-ge', 10, 'მკურნალობის შემდგომ ეტაპზე ინდივიდუალური კომბინაციები კიდევ უფრო მეტად აუმჯობესებს შედეგებს:\r\n<ul>\r\n 	<li>შრატების კომბინაციები ინდივიდუალური მოვლისთვის საჭირო სხვადასხვა საჭიროებების სიღრმისეული მკურნალობის უზრუნველსაყოფად.</li>\r\n 	<li>რამდენიმე ნიღბის კომბინაცია შრატების სასარგებლო თვისებების დამატებისათვის.</li>\r\n</ul>\r\n', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(990, 3035, 'ka-ge', 10, 'ჟიზელ დელორმის პროდუქტის ფორმულები საკმაოდ რთულია რამოდენიმე მიზეზის გამო. <br>პირველი, მომთხოვნი კლიენტების მოლოდინების დასაკმაყოფილებლად შექმნილი ფორმულა მრავალი აქტიური ინგრედიენტის შემცველ ფორმულებს ნიშნავს, რომელიც შედეგის გარანტიაა<br>  ', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
(991, 3029, 'ka-ge', 10, 'მეორე არის ჩვენი გალენური ფორმულების სპეციფიკურობა. ჩვენ გვსურს მივაღწიოთ საუკეთესო შესაძლო ბიოშეღწევადობას, ეს კი ჩვენი აქტიური ინგრედიენტების მიერ არის შესაძლებელი, რაც გულისხმობს დახვეწილი გალენური ფორმულების გამოყენებას, როგორიცაა ემულსიები.    ', NULL, 1, 'local', 0, '2026-01-17 05:49:06'),
