(1026, 3129, 'ka-ge', 10, 'G.D.I.-სთან დასაკავშირებლად, შეგიძლიათ მისწეროთ gisele.online@gisele-delorme.com-ზე ან პირდაპირ საიტზე კონტაქტის „კონტაქტი“ განყოფილების მეშვეობით, თქვენი საკონტაქტო ინფორმაციის და თქვენი მოთხოვნის მიზეზის მითითებით.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1027, 3130, 'ka-ge', 10, 'საიტის აკომოდაცია', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1028, 3131, 'ka-ge', 10, 'საიტს საფრანგეთში მართავს კომპანია OVH – 2, rue Kellermann – 59100 Roubaix – France.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1029, 3132, 'ka-ge', 10, 'გაწეული მომსახურების აღწერა', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1030, 3133, 'ka-ge', 10, 'ვებგვერდის www.gisele-delorme.com მიზანია პროდუქციის შესახებ ინფორმაციის მიწოდება და ონლაინ შესყიდვების განხორციელება. საიტის ცდილობს,მაქსიმალურად ზუსტი ინფორმაციის მიწოდებას.\r\n\r\nთუმცა, ის არ არის პასუხისმგებელი განახლებაში არსებულ გამოტოვებებზე, უზუსტობებსა და ნაკლოვანებებზე, იქნება ეს მისი ან ამ ინფორმაციის მიმწოდებელი მესამე მხარის პარტნიორების მიერ.\r\n\r\nსაიტზე შემოთავაზებული ყველა ინფორმაცია მოცემულია მითითების სახით, არ არის ამომწურავი და შესაძლოა განვითარდეს. ისინი მოცემულია ონლაინ განთავსების შემდეგ განხორციელებული ცვლილებების გათვალისწინებით.3', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1031, 3134, 'ka-ge', 10, 'ინტელექტუალური საკუთრება და ფალსიფიცირებული პროდუქცია', NULL, 1, 'local', 0, '2026-01-17 14:10:42');
INSERT INTO `wp_icl_string_translations` (`id`, `string_id`, `language`, `status`, `value`, `mo_string`, `translator_id`, `translation_service`, `batch_id`, `translation_date`) VALUES
(1032, 3135, 'ka-ge', 10, 'საიტის მფლობელი ფლობს ინტელექტუალური საკუთრების უფლებებს ან ფლობს საიტზე ხელმისაწვდომ ყველა ელემენტზე, მათ შორის ტექსტზე, სურათებზე, გრაფიკაზე, ლოგოზე, ხატულებზე, ხმებზე, პროგრამულ უზრუნველყოფაზე გამოყენების უფლებას.<br>საიტის ელემენტების ნებისმიერი რეპროდუცირება, წარმოდგენა, მოდიფიკაცია, გამოქვეყნება, სრული ან ნაწილობრივი ადაპტაცია, გამოყენებული საშუალებებისა თუ პროცესის მიუხედავად, აკრძალულია, თუ წინასწარ არ არის წერილობითი ნებართვა გაგზავნილი ელექტრონული ფოსტით: gisele.online@gisele-delorme.com.<br>საიტის ან მისი რომელიმე ელემენტის ნებისმიერი უნებართვო გამოყენება ჩაითვლება დარღვევად და დაისჯება ინტელექტუალური საკუთრების კოდექსის L.335-2 და შემდგომი მუხლების დებულებების შესაბამისად.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1033, 3136, 'ka-ge', 10, 'HYPERLINKS', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1034, 3137, 'ka-ge', 10, 'საიტი gisele-delorme.com სხვა მრავალ ვებსაიტზე მიუთითებს. G.D.I. არ არის პასუხისმგებელი ამ საიტების შინაარსსა და კონფიდენციალურობის პოლიტიკაზე. G.D.I. არ არის პასუხისმგებელი მათი გამოყენების შედეგად მიყენებულ ნებისმიერ პირდაპირ ან ირიბ ზიანზე: კერძოდ, ამ საიტებზე და მათთან დაკავშირებულ საიტებზე წვდომიდან, ასევე ზარალზე, არაშემზღუდავ, ფინანსურ ან კომერციულ ზიანზე, ექსპლუატაციის დაკარგვაზე, მონაცემთა დაკარგვაზე, მაშინაც კი, თუ წინასწარ შეგვეძლო ამის შესახებ შეტყობინების მიღება.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1035, 3138, 'ka-ge', 10, 'მონაცემთა დამუშავება', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1036, 3139, 'ka-ge', 10, 'საიტი CNIL-ისთვის (https://www.cnil.fr/) რეგისტრირებულია DPO-84171 ნომრით.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1037, 3140, 'ka-ge', 10, 'G.D.I. აგროვებს თქვენს მონაცემებს თქვენი საკონტაქტო მოთხოვნის ან შესყიდვის დასამუშავებლად. საჭირო მონაცემები საჭიროა თქვენი მოთხოვნის შემდგომი განხილვისთვის. მონაცემთა დაცვის შესახებ კანონის შესაბამისად, თქვენ გაქვთ თქვენს მონაცემებზე წვდომის, მათზე კორექტირების და წაშლის უფლება. თქვენ ასევე შეგიძლიათ გააპროტესტოთ თქვენი მონაცემების გამოყენება ლეგიტიმური მიზეზით. მხოლოდ თქვენ შეგიძლიათ განახორციელოთ ეს უფლებები თქვენს მონაცემებზე დაკავშირების გზით: G.D.I., Correspondent Informatique et libertés, 88 bis, rue Michel Ange, 75016 Paris ან gisele.online@gisele-delorme.com, წერილის სათაურში მიუთითეთ „პირთა უფლებები“ და დაურთეთ თქვენი პირადობის დამადასტურებელი დოკუმენტის ასლი.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1038, 3141, 'ka-ge', 10, 'ვალდებულებები', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1039, 3142, 'ka-ge', 10, 'G.D.I. იღებს ვალდებულებას, პატივი სცეს მყიდველებთან დაკავშირებული მონაცემების კონფიდენციალურობას. ეს კონფიდენციალურობის პოლიტიკა აღწერს პერსონალურ მონაცემებს, რომლებიც გროვდება G.D.I-ში შეკვეთის განთავსებისას. იგი ასევე განმარტავს, თუ როგორ გამოიყენება, გაზიარდება და დაცულია თქვენი პერსონალური მონაცემები, რა არჩევანი გაქვთ თქვენს პერსონალურ მონაცემებთან დაკავშირებით და როგორ დაგვიკავშირდეთ.\r\n\r\nჩვენ გთხოვთ გარკვეულ პერსონალურ მონაცემებს, რათა მოგაწოდოთ თქვენს მიერ მოთხოვნილი პროდუქტები ან მომსახურება, როდესაც შეკვეთას განათავსებთ საიტზე.\r\n', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1040, 3143, 'ka-ge', 10, 'ეს პერსონალური მონაცემები მოიცავს თქვენს:\r\n<ul>\r\n 	<li>საკონტაქტო ინფორმაციას, როგორიცაა ელექტრონული ფოსტა, ტელეფონის ნომერი და მიწოდების მისამართი.</li>\r\n 	<li>თქვენი შესყიდვებისა და გადახდის ისტორია.</li>\r\n</ul>\r\n', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1041, 3144, 'ka-ge', 10, 'G.D.I უზიარებს თქვენს პერსონალურ მონაცემებს:\r\n<ul>\r\n 	<li>G.D.I.-ის სუბიექტებს ზემოთ მითითებული მიზნებისა და პირობების შესაბამისად.</li>\r\n 	<li>მესამე მხარის მომსახურების მიმწოდებლებს, რომლებიც ამუშავებენ პერსონალურ მონაცემებს G.D.I.-ის სახელით, მაგალითად, გადახდებისა და საკრედიტო ბარათების, გადაზიდვებისა და მიწოდებების, თქვენი მონაცემების ჰოსტინგის, ადმინისტრირებისა და მართვის, ელექტრონული ფოსტის გავრცელების - თქვენი თანხმობით.</li>\r\n 	<li>სხვა მესამე მხარეებს, იმ შემთხვევაში, თუ ეს აუცილებელია:</li>\r\n 	<li>ადმინისტრაციული მოთხოვნის, სასამართლოს გადაწყვეტილების ან მოქმედი კანონმდებლობის შესასრულებლად.</li>\r\n 	<li>დაიცავით თავი მესამე მხარის პრეტენზიებისგან.</li>\r\n 	<li>დახმარება გაუწიეთ თაღლითობის ან გამოძიების თავიდან აცილებაში (მაგ., გაყალბება).</li>\r\n</ul>\r\n', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1042, 3145, 'ka-ge', 10, 'ნებისმიერი სხვა მესამე მხარე იმ შემთხვევებში, როდესაც თქვენ გამოხატეთ თქვენი თანხმობა.<br>როდესაც ჩვენ ვიყენებთ მესამე მხარის პროვაიდერების მომსახურებას, ჩვენ ვდებთ კონტრაქტებს, რომლებიც ავალდებულებს მათ განახორციელონ შესაბამისი ტექნიკური და ორგანიზაციული ზომები თქვენი პერსონალური მონაცემების დასაცავად.<br>საკრედიტო ბარათით გადახდების შემთხვევაში, მონაცემები არ ინახება.<br>ჩვენ ასევე გადავცემთ თქვენს პერსონალურ მონაცემებს იმ შემთხვევაში, თუ ჩვენ ვახორციელებთ ჩვენი ბიზნესის ან აქტივების სრულად ან ნაწილობრივ დათმობას ან გადაცემას (მათ შორის, რეორგანიზაციის, დათმობის, დაშლის ან ლიკვიდაციის შემთხვევაში).', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1043, 3146, 'ka-ge', 10, 'გაზეთი', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1044, 3147, 'ka-ge', 10, 'თქვენი თანხმობის შემთხვევაში, თქვენი მონაცემები დაექვემდებარება ავტომატიზირებულ დამუშავებას ჩვენი ქმედებების ელექტრონული ფოსტით ხელშეწყობის მიზნით. ისინი ინახება თქვენთან ბოლო კონტაქტიდან ან გამოწერის გაუქმებიდან მაქსიმუმ ხუთი წლის განმავლობაში. 1978 წლის 6 იანვრის შესწორებული მონაცემთა დაცვის შესახებ კანონის შესაბამისად, თქვენ გაქვთ თქვენს მონაცემებზე წვდომის, მათი გასწორების, წაშლის და გადატანის უფლება, რომლის განხორციელებაც შეგიძლიათ gisele.online@gisele-delorme.com-ზე დაკავშირების გზით.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1045, 3148, 'ka-ge', 10, 'მომხმარებლის ანგარიში', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1046, 3149, 'ka-ge', 10, 'We collect this information in order to process your orders. ჩვენ ამ ინფორმაციას თქვენი შეკვეთების დასამუშავებლად ვაგროვებთ. ის ერთი წლის განმავლობაში ინახება და არ გამოიყენება სხვა მიზნებისთვის და არც გადაეცემა მესამე პირებს. თქვენთან დაკავშირებულ მონაცემებზე წვდომის, მათი შეცვლის, წაშლისა და პორტაბელურობის უფლების განსახორციელებლად, შეგიძლიათ მოგვწეროთ შემდეგ მისამართზე: gisele.online@gisele-delorme.com.', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1047, 3150, 'ka-ge', 10, 'თქვენი უფლებები', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
(1048, 3151, 'ka-ge', 10, 'თქვენ გაქვთ უფლება მოითხოვოთ: თქვენს პერსონალურ მონაცემებზე წვდომა, თქვენი პერსონალური მონაცემების გასწორება ან თქვენი პერსონალური მონაცემების წაშლა ან შეზღუდვა მოქმედი კანონმდებლობით გათვალისწინებულ გარკვეულ შემთხვევებში. ეს უფლებები აბსოლუტური არ არის. საიტზე შესვლისას თქვენი პერსონალური მონაცემების დამუშავებაზე თქვენი თანხმობა შეიძლება ნებისმიერ დროს გააუქმოთ.\r\n\r\nთუ გსურთ თქვენი პერსონალური მონაცემების ასლის მოთხოვნა ან თქვენი რომელიმე უფლების გამოყენება, გთხოვთ, დაგვიკავშირდეთ ელექტრონულ ფოსტაზე gisele.online@gisele-delorme.com\r\n', NULL, 1, 'local', 0, '2026-01-17 14:10:42'),
