(6690, 32265, '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:870;s:6:\"height\";i:1110;s:4:\"file\";s:29:\"2026/01/Serum-hydratation.jpg\";s:8:\"filesize\";i:18186;s:5:\"sizes\";a:6:{s:6:\"medium\";a:5:{s:4:\"file\";s:29:\"Serum-hydratation-235x300.jpg\";s:5:\"width\";i:235;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:6234;}s:5:\"large\";a:5:{s:4:\"file\";s:30:\"Serum-hydratation-803x1024.jpg\";s:5:\"width\";i:803;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:39083;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:29:\"Serum-hydratation-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:3114;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:29:\"Serum-hydratation-768x980.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:980;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:36683;}s:21:\"woocommerce_thumbnail\";a:6:{s:4:\"file\";s:29:\"Serum-hydratation-600x600.jpg\";s:5:\"width\";i:600;s:6:\"height\";i:600;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:23343;s:9:\"uncropped\";b:0;}s:29:\"woocommerce_gallery_thumbnail\";a:5:{s:4:\"file\";s:29:\"Serum-hydratation-100x100.jpg\";s:5:\"width\";i:100;s:6:\"height\";i:100;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:1926;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
