(173, 1, '2026-01-19 11:01:13', '2026-01-19 11:01:13', '<div class=\"borderdiv\">\r\n<strong>Subscribe to our Newsletter:</strong>\r\n<p class=\"mailchimp-input-icon\">\r\n	<label>Email address: </label>\r\n	<input type=\"email\" name=\"EMAIL\" placeholder=\"E-mail*\" required />\r\n</p>\r\n<p>\r\n <input name=\"AGREE_TO_TERMS\" type=\"checkbox\" value=\"1\" required=\"\"> <a id=\"mail_checkbox\" href=\"/mentions-legales\" target=\"_blank\" rel=\"noopener\">I agree to receive emails from Gisele Delorme</a>\r\n</p>\r\n<p>\r\n<input id=\"msubmit_btn\" type=\"submit\" value=\"Sign up\">\r\n</p>\r\n</div>', 'Newslatter', '', 'publish', 'closed', 'closed', '', 'default-sign-up-form', '', '', '2026-01-19 11:01:13', '2026-01-19 11:01:13', '', 0, 'http://dummy.xtemos.com/basel/mc4wp-form/default-sign-up-form/', 0, 'mc4wp-form', '', 0),
