nt a suspendisse sem.[/basel_info_box][basel_button color=\"primary\" size=\"small\" align=\"center\" title=\"VEW MORE\" link=\"#\"][/vc_column][/vc_row][vc_row full_width=\"stretch_row_content\" css=\".vc_custom_1504880170983{margin-bottom: 8vh !important;}\" el_class=\"overflow-visible\"][vc_column css=\".vc_custom_1504879593746{padding-top: 0px !important;}\"][basel_row_divider style=\"paint-stroke\" color=\"#f6f6f6\"][/vc_column][/vc_row][vc_row css=\".vc_custom_1505140015814{margin-bottom: 6vh !important;}\"][vc_column][vc_single_image image=\"1182\" img_size=\"full\" alignment=\"center\" css=\".vc_custom_1505218567884{margin-bottom: 15px !important;}\"][basel_title tag=\"h3\" title=\"OUR BAKERY BLOG\" after_title=\"A diam scelerisque quis egestas dui arcu mus viverra adipiscing.\" css=\".vc_custom_1505217536605{margin-bottom: 40px !important;}\"][basel_posts slides_per_view=\"3\" hide_pagination_control=\"yes\" posts_query=\"size:4|order_by:date|post_type:,post\"][/vc_column][/vc_row][vc_row full_width=\"stretch_row_content_no_spaces\" equal_height=\"yes\" content_placement=\"middle\" css=\".vc_custom_1505215160621{margin-bottom: -40px !important;background-color: #f2f2f2 !important;}\"][vc_column css=\".vc_custom_1505218603724{padding-top: 50px !important;padding-right: 15% !important;padding-bottom: 50px !important;padding-left: 15% !important;background-image: url(http://dummy.xtemos.com/basel/vers/wp-content/uploads/sites/3/2017/09/bakery-pattrn-2.jpg?id=1191) !important;background-position: 0 0 !important;background-repeat: repeat !important;}\" offset=\"vc_col-lg-5 vc_col-md-12\"][vc_single_image image=\"1182\" img_size=\"full\" alignment=\"center\" css=\".vc_custom_1505218578277{margin-bottom: 15px !important;}\"][basel_title tag=\"h3\" title=\"OPENING HOURS\" after_title=\"Gravida purus auctor atnam\" css=\".vc_custom_1505123263415{margin-bottom: 40px !important;}\"][basel_menu_price price=\"9:00 AM - 7:00 PM\" description=\"MONDAY - FRIDAY\"][basel_me