(3, 'Bullet Bar', 'bullet-bar', 'bullets', '.bullet-bar.tp-bullets {\n}\n.bullet-bar.tp-bullets:before {\n	content:\\\" \\\";\n	position:absolute;\n	width:100%;\n	height:100%;\n	background:transparent;\n	padding:10px;\n	margin-left:-10px;margin-top:-10px;\n	box-sizing:content-box;\n}\n.bullet-bar .tp-bullet {\n	width:60px;\n	height:3px;\n	position:absolute;\n	background:#aaa;\n    background:rgba(204,204,204,0.5);\n	cursor: pointer;\n	box-sizing:content-box;\n}\n.bullet-bar .tp-bullet.rs-touchhover,\n.bullet-bar .tp-bullet.selected {\n	 background:rgba(204,204,204,1);\n}\n.bullet-bar .tp-bullet-image {\n}\n.bullet-bar .tp-bullet-title {\n}\n', '', '{\"dim\":{\"width\":160,\"height\":160},\"placeholders\":{},\"presets\":{},\"version\":\"6.0.0\"}'),
